# DateTimePicker 时间选择器

## 示例

## 引入

全局引入，在 miniprogram 根目录下的`app.json`中配置，局部引入，在需要引入的页面或组件的`index.json`中配置。

```json
"usingComponents": {
"t-date-time-picker": "tdesign-miniprogram/date-time-picker/date-time-picker"
}
```

## 代码演示

[在开发者工具中预览效果](https://developers.weixin.qq.com/s/hts3GMmc8c5q)

> Tips: 请确保开发者工具为打开状态。导入开发者工具后，依次执行：npm i > 构建npm包 > 勾选 "将JS编译成ES5"

### 组件类型

#### 年月日选择器

**WXML** (`html`):
```html
<t-cell
title="选择日期"
hover
note="{{dateText || ''}}"
arrow
data-mode="date"
bindtap="showPicker"
class="test"
t-class="panel-item"
/>

<!-- 年月日 -->
<t-date-time-picker
auto-close
title="选择日期"
showWeek
visible="{{dateVisible}}"
mode="date"
default-value="{{date}}"
format="YYYY-MM-DD ddd"
filter="{{filter}}"
formatter="{{formatter}}"
popup-props="{{popupProps}}"
bindchange="onConfirm"
bindpick="onColumnChange"
bindcancel="hidePicker"
bindclose="handleClose"
/>

```

**JS** (`javascript`):
```javascript
const calendarMonth = [
'January',
'February',
'March',
'April',
'May',
'June',
'July',
'August',
'September',
'October',
'November',
'December',
];

Page({
data: {
mode: '',
dateVisible: false,
date: new Date('2021-12-23').getTime(), // 支持时间戳传入
dateText: '',
filter(type, options) {
if (type === 'year') {
return options.sort((a, b) => b.value - a.value);
}
return options;
},
popupProps: {
usingCustomNavbar: true,
},

formatter(item, index) {
if (index === 1) {
const label = item.label.slice(0, -1);
return {
value: item.value,
label: calendarMonth[Number(label) - 1],
};
}
if (index === 2) {
const [dateValue, weekValue] = item.label.split(' ');
const dateSuffixes = {
1: 'st',
2: 'nd',
3: 'rd',
};
const weekMap = {
周一: 'Mon.',
周二: 'Tues.',
周三: 'Wed.',
周四: 'Thurs.',
周五: 'Fri.',
周六: 'Sat.',
周日: 'Sun.',
};
const label = dateValue.slice(0, -1);

return {
value: item.value,
label: `${label}${dateSuffixes[label] || 'th'} ${weekMap[weekValue]}`,
};
}

return {
value: item.value,
label: item.label.slice(0, -1),
};
},
},
showPicker(e) {
const { mode } = e.currentTarget.dataset;
this.setData({
mode,
[`${mode}Visible`]: true,
});
},

handleClose(e) {
console.log('handleClose:', e);
},

onConfirm(e) {
const { value } = e.detail;
const { mode } = this.data;

console.log('confirm', value);

this.setData({
[mode]: value,
[`${mode}Text`]: value,
});
},

onColumnChange(e) {
console.log('pick', e.detail.value);
},
});

```

**CSS** (`css`):
```css
.panel-item {
margin-bottom: 32rpx;
}

.panel-item::after {
border: 0;
}

```

**JSON** (`javascript`):
```javascript
{
"usingComponents": {
"t-cell": "tdesign-miniprogram/cell/cell",
"t-date-time-picker": "tdesign-miniprogram/date-time-picker/date-time-picker"
}
}

```

#### 年月选择器

**WXML** (`html`):
```html
<t-cell title="选择日期" hover note="{{monthText}}" arrow data-mode="month" bindtap="showPicker" t-class="panel-item" />

<!-- 年月 -->
<t-date-time-picker
title="选择日期"
visible="{{monthVisible}}"
mode="month"
value="{{month}}"
format="YYYY-MM"
bindchange="onConfirm"
bindpick="onColumnChange"
bindcancel="hidePicker"
start="{{start}}"
end="{{end}}"
/>

```

**JS** (`javascript`):
```javascript
Page({
data: {
mode: '',
monthVisible: false,
month: '2021-09',
monthText: '',

// 指定选择区间起始值
start: '2000-01-01 00:00:00',
end: '2030-09-09 12:12:12',
},
showPicker(e) {
const { mode } = e.currentTarget.dataset;
this.setData({
mode,
[`${mode}Visible`]: true,
});
},
hidePicker() {
const { mode } = this.data;
this.setData({
[`${mode}Visible`]: false,
});
},
onConfirm(e) {
const { value } = e.detail;
const { mode } = this.data;

console.log('confirm', value);

this.setData({
[mode]: value,
[`${mode}Text`]: value,
});

this.hidePicker();
},

onColumnChange(e) {
console.log('pick', e.detail.value);
},
});

